165	// only the witness representation differs.
166	func (s *Store) CheckInput(name string, version int, hash string, witness Witness) (CheckResult, error) {
167		if err := validateCheckRequest(name, version, hash); err != nil {
168			return CheckResult{}, err
169		}
170		var result CheckResult
171		err := s.withLockRead(func() error {
172			def, boundHash, gerr := s.boundCheckDefinition(name, version, hash)
173			if gerr != nil {
174				return gerr
175			}
176			parsed, perr := parseWitnessValues(witness.Public, witness.Private, def.public, def.private, def.modulus)
177			if perr != nil {
178				return tagInputFormatError(perr)
179			}
