186	// CheckInputFile is CheckInput with the witness read from a JSON file. It
187	// shares every gating, binding and evaluation rule with CheckInput; the only
188	// differences are how the witness is supplied (a strict JSON document that
189	// must explicitly contain both string arrays, even when empty) and that an
190	// unreadable or malformed file is reported as an input format error.
191	//
192	// The file is read first, so a missing or unreadable file keeps its read
193	// error; but once the file can be read, all binding gating still runs
194	// against the live store — an unknown version, a draft, a missing artifact
195	// or a wrong hash is reported before any complaint about the file's
196	// contents.
197	func (s *Store) CheckInputFile(name string, version int, hash, path string) (CheckResult, error) {
198		if err := validateCheckRequest(name, version, hash); err != nil {
199			return CheckResult{}, err
200		}
