213				return tagInputFormatError(derr)
214			}
215			parsed, perr := parseWitnessValues(pubValues, privValues, def.public, def.private, def.modulus)
216			if perr != nil {
217				return tagInputFormatError(perr)
218			}
219			result = evaluateCheck(def, parsed, boundHash)
220			return nil
221		})
222		return result, err
223	}
224	
225	// validateCheckRequest covers the request-shape checks common to both
226	// entry points: an explicit non-whitespace circuit key and a non-empty
227	// artifact hash.
228	func validateCheckRequest(name string, version int, hash string) error {
229		if err := validateCircuitKey(name, version); err != nil {
230			return err
231		}
232		if hash == "" {
233			return invalidf("an artifact hash is required to check inputs")
234		}
235		return nil
236	}
