239	// to, in the required order: the version must exist and be frozen, its
240	// compiled artifact must exist, the supplied hash must equal that
241	// artifact's hash (artifacts of other names or versions never qualify), and
242	// the stored definition behind the artifact must be readable. It returns
243	// the canonical definition and the bound artifact hash.
244	//
245	// Callers must hold the store read lock.
246	func (s *Store) boundCheckDefinition(name string, version int, hash string) (*canonicalDefinition, string, error) {
247		circuit := findCircuit(s.data.Circuits, name, version)
248		if circuit == nil {
249			return nil, "", notFoundf("circuit %q version %d does not exist", name, version)
250		}
251		if !circuit.Frozen {
252			return nil, "", notFrozenf("circuit %q version %d must be frozen before inputs can be checked", name, version)
253		}
254		artifact := findArtifact(s.data.Artifacts, name, version)
255		if artifact == nil {
