257		}
258		if artifact.Hash != hash {
259			return nil, "", artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
260				hash, name, version, artifact.Hash)
261		}
262		if circuit.Definition == nil {
263			return nil, "", corruptf("artifact for %q v%d exists but its definition is missing", name, version)
264		}
265		parsed, perr := definitionFromPersist(*circuit.Definition, circuit.PublicInputs, circuit.PrivateInputs)
