1	package zkcircuit
2	
3	import "fmt"
4	
5	// Failure kinds reported by the persistent workbench. Callers can inspect a
6	// returned error with errors.Is to distinguish rule violations; human-facing
7	// clients may also use the messages directly.
8	var (
9		// ErrInvalidArgument is a malformed request (empty name, bad counts, …).
10		ErrInvalidArgument = StoreError{Kind: "invalid argument"}
11		// ErrNotFound means the referenced circuit version does not exist.
12		ErrNotFound = StoreError{Kind: "not found"}
13		// ErrConflict means an existing record disagrees with the request.
14		ErrConflict = StoreError{Kind: "conflict"}
15		// ErrDraftRequired means an operation requires a draft circuit version.
16		ErrDraftRequired = StoreError{Kind: "draft required"}
17		// ErrFrozen means the circuit version is frozen and cannot be modified.
18		ErrFrozen = StoreError{Kind: "frozen"}
19		// ErrNotFrozen means trusted setup or a job requires a frozen version.
20		ErrNotFrozen = StoreError{Kind: "not frozen"}
21		// ErrSetupMissing means the frozen version has no recorded trusted setup.
22		ErrSetupMissing = StoreError{Kind: "trusted setup missing"}
23		// ErrUnsupportedKind means a job kind other than prove was submitted.
24		ErrUnsupportedKind = StoreError{Kind: "unsupported job kind"}
25		// ErrDefinitionMissing means a frozen version has registered counts but no
26		// imported constraint definition, so it cannot be compiled.
27		ErrDefinitionMissing = StoreError{Kind: "constraint definition missing"}
28		// ErrArtifactMissing means the version has no compiled artifact.
29		ErrArtifactMissing = StoreError{Kind: "compiled artifact missing"}
30		// ErrArtifactMismatch means the supplied hash does not belong to the
31		// target version's compiled artifact.
32		ErrArtifactMismatch = StoreError{Kind: "artifact mismatch"}
33		// ErrInvalidInput means a witness document is malformed or does not match
34		// the version's declared input layout.
35		ErrInvalidInput = StoreError{Kind: "input format error"}
36		// ErrDataCorrupt means the on-disk data file cannot be read safely.
37		ErrDataCorrupt = StoreError{Kind: "data corrupt"}
38	)
39	
40	// StoreError is a domain error with a human-readable Detail tagged with a
41	// stable Kind. The zero value is not used; construct via the helpers below.
42	type StoreError struct {
43		Kind   string
44		Detail string
45	}
46	
47	func (e StoreError) Error() string {
